    'Kami menunjukkan dari mana asal total pakan yang dikonsumsi. Penghitung waktu, pakan yang dikonsumsi dilakukan oleh penghitung waktu. Silo, pakan yang dikonsumsi adalah pakan yang dikonsumsi di semua silo yang terhubung. Silo (1,2,3), kami menunjukkan silo mana yang akan menghitung pakan yang dikonsumsi.'
